                if ($null -ne $_.PSObject.Properties["Problem"] -and $null -ne $_.Problem) { $prob = [int]$_.Problem }
                [pscustomobject]@{
                    Name = $devName
                    Class = [string]$_.Class
                    Status = [string]$_.Status
                    Problem = $prob
                    InstanceId = [string]$_.InstanceId
